/**
 * ApiException：携带分段错误码的自定义异常（§3.1 错误信封 {code,message,details}）。
 * 业务代码推荐抛出本异常（或直接使用 Nest 内置异常 + {code,message} 对象响应体，异常过滤器两者都兼容）。
 */
import { HttpException } from '@nestjs/common';
export interface ErrorDetails {
    /** 40902 状态迁移非法时必带：允许迁移枚举（前端据此渲染可用按钮，§3.3 补充规则） */
    allowed_transitions?: unknown[];
    [key: string]: unknown;
}
export declare class ApiException extends HttpException {
    constructor(code: number, message: string, status?: number, details?: unknown);
    /** 40001 参数校验失败 */
    static badRequest(message: string, details?: unknown): ApiException;
    /** 40101 认证失败（access 过期时前端用 refresh 换新） */
    static unauthorized(message?: string): ApiException;
    /** 40301 权限不足（跨租户/跨项目默认此码） */
    static forbidden(message?: string): ApiException;
    /** 40401 资源不存在或不可见（防存在性探测） */
    static notFound(message?: string): ApiException;
    /** 40901 乐观锁冲突（version 不匹配，前端刷新重试） */
    static optimisticLock(message?: string): ApiException;
    /** 40902 状态迁移非法（details 必带 allowed_transitions） */
    static illegalTransition(from: string, to: string, allowedTransitions: unknown[]): ApiException;
    /** 42901 请求频率超限 */
    static rateLimited(message?: string): ApiException;
    /** 502 AI 服务不可达 */
    static aiUnavailable(message?: string): ApiException;
    /** 503 DB/Redis 不可用（触发降级路径） */
    static dependencyUnavailable(message?: string): ApiException;
}
